def count_vowels(strings):
    vowel_count = {}
    vowels = "aeiou"

    for item in strings:
        if not isinstance(item, str):
            continue

        count = 0
        for char in item.lower():
            if char in vowels:
                count += 1

        vowel_count[item] = count

    return vowel_count
```

