from typing import List

def find_all_anagrams(s: str, p: str) -> List[int]:
    from collections import Counter

    if not s or not p:
        return []

    p_count = Counter(p)
    s_count = Counter()

    result = []

    p_len = len(p)
    s_len = len(s)

    if p_len > s_len:
        return []

    for i in range(p_len):
        s_count[s[i]] += 1

    if s_count == p_count:
        result.append(0)

    for i in range(p_len, s_len):
        s_count[s[i]] += 1
        s_count[s[i - p_len]] -= 1

        if s_count[s[i - p_len]] == 0:
            del s_count[s[i - p_len]]

        if s_count == p_count:
            result.append(i - p_len + 1)

    return result
```

