from typing import List

def longest_subarray_within_range(nums: List[int], k: int) -> int:
    if not nums:
        return 0

    max_q = []
    min_q = []
    longest = 0
    left = 0

    for right, num in enumerate(nums):
        while max_q and num > nums[max_q[-1]]:
            max_q.pop()
        max_q.append(right)

        while min_q and num < nums[min_q[-1]]:
            min_q.pop()
        min_q.append(right)

        while max_q and min_q and nums[max_q[0]] - nums[min_q[0]] > k:
            left += 1
            while max_q and max_q[0] < left:
                max_q.pop(0)
            while min_q and min_q[0] < left:
                min_q.pop(0)

        longest = max(longest, right - left + 1)

    return longest
```

