def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def find_lcm(numbers: List[int]) -> int:
    if not numbers:
        return 0

    lcm = numbers[0]
    for num in numbers[1:]:
        lcm = abs(lcm * num) // gcd(lcm, num)

    return lcm
```

