def elements_appearing_k_times(lst, k):
    from collections import defaultdict

    count = defaultdict(int)
    for num in lst:
        count[num] += 1

    result = []
    for num in lst:
        if count[num] == k and num not in result:
            result.append(num)

    return result
```

