def max_sum_non_adjacent(nums):
    if not nums:
        return 0

    if len(nums) == 1:
        return nums[0]

    include = 0
    exclude = 0

    for num in nums:
        exclude_new = max(exclude, include)
        include = exclude + num
        exclude = exclude_new

    return max(exclude, include)
