import re

def is_valid_email(email: str) -> bool:
    email = email.strip()

    if len(email) == 0:
        return False

    if email.count('@') != 1:
        return False

    local_part, domain_part = email.split('@')

    if len(local_part) == 0 or len(domain_part) == 0:
        return False

    if ' ' in local_part:
        return False

    if not re.match(r'^[a-zA-Z0-9._-]+$', local_part):
        return False

    if domain_part.count('.') == 0:
        return False

    domain_parts = domain_part.split('.')
    if len(domain_parts) < 2:
        return False

    if not re.match(r'^[a-zA-Z0-9.-]+$', domain_part):
        return False

    return True
```

