def shift_string(s, n):
    shifted = []
    for char in s:
        if 'a' <= char <= 'z':
            shifted_char = chr((ord(char) - ord('a') + n) % 26 + ord('a'))
            shifted.append(shifted_char)
        elif 'A' <= char <= 'Z':
            shifted_char = chr((ord(char) - ord('A') + n) % 26 + ord('A'))
            shifted.append(shifted_char)
        else:
            shifted.append(char)
    return ''.join(shifted)
