from typing import List, Tuple

def longest_path(edges: List[Tuple[int, int]]) -> List[int]:
    from collections import defaultdict

    if not edges:
        return []

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        nonlocal farthest_node, farthest_distance
        distance = 0
        for neighbor in graph[node]:
            if neighbor != parent:
                dist = dfs(neighbor, node) + 1
                if dist > distance:
                    distance = dist
        if distance > farthest_distance:
            farthest_distance = distance
            farthest_node = node
        return distance

    farthest_node = -1
    farthest_distance = 0
    dfs(0, -1)

    path = []
    visited = set()

    def find_path(node, parent):
        path.append(node)
        visited.add(node)
        if node == farthest_node:
            return True
        for neighbor in graph[node]:
            if neighbor != parent and neighbor not in visited:
                if find_path(neighbor, node):
                    return True
        path.pop()
        visited.remove(node)
        return False

    find_path(farthest_node, -1)
    return path
```

