from typing import List
import heapq

def get_skyline(buildings: List[List[int]]) -> List[List[int]]:
    if not buildings:
        return []

    events = []
    for left, right, height in buildings:
        events.append((left, -height, right))
        events.append((right, 0, 0))

    events.sort()

    skyline = []
    max_heap = [(0, float('inf'))]

    for x, neg_height, right in events:
        while x >= max_heap[0][1]:
            heapq.heappop(max_heap)

        if neg_height:
            heapq.heappush(max_heap, (neg_height, right))

        if skyline and x == skyline[-1][0]:
            continue

        current_max_height = -max_heap[0][0]
        if not skyline or current_max_height != skyline[-1][1]:
            skyline.append([x, current_max_height])

    return skyline
```

