def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def canBeSumOfTwoPrimes(n: int) -> bool:
    if n < 4:
        return False

    for i in range(2, n):
        if is_prime(i) and is_prime(n - i):
            return True
    return False
```

