def is_anagram(s1, s2):
    # Filter out non-alphabetic characters and convert to lowercase
    filtered_s1 = [char.lower() for char in s1 if char.isalpha()]
    filtered_s2 = [char.lower() for char in s2 if char.isalpha()]

    # If the lengths of the filtered strings are different, they cannot be anagrams
    if len(filtered_s1) != len(filtered_s2):
        return False

    # Count the frequency of each character in both strings
    count_s1 = {}
    count_s2 = {}

    for char in filtered_s1:
        if char in count_s1:
            count_s1[char] += 1
        else:
            count_s1[char] = 1

    for char in filtered_s2:
        if char in count_s2:
            count_s2[char] += 1
        else:
            count_s2[char] = 1

    # Compare the frequency counts
    return count_s1 == count_s2
