def find_max_unique_substring(s: str) -> str:
    char_map = {}
    max_length = 0
    max_substring = ""
    start = 0

    for end, char in enumerate(s):
        if char in char_map:
            start = max(start, char_map[char] + 1)
        char_map[char] = end

        if end - start + 1 > max_length:
            max_length = end - start + 1
            max_substring = s[start:end + 1]

    return max_substring


def min_window_substring(s: str, t: str) -> str:
    from collections import defaultdict

    if not t or not s:
        return ""

    char_count = defaultdict(int)
    for char in t:
        char_count[char] += 1

    required = len(char_count)
    formed = 0
    char_window = {}

    left = 0
    min_length = float('inf')
    min_substring = ""

    for right in range(len(s)):
        char = s[right]
        char_window[char] = char_window.get(char, 0) + 1

        if char in char_count and char_window[char] == char_count[char]:
            formed += 1

        while left <= right and formed == required:
            char = s[left]

            if right - left + 1 < min_length:
                min_length = right - left + 1
                min_substring = s[left:right + 1]

            char_window[char] -= 1
            if char in char_count and char_window[char] < char_count[char]:
                formed -= 1

            left += 1

    return min_substring
```

