def calculate_binary_gap(number: int) -> int:
    if not isinstance(number, int) or number < 0:
        raise TypeError("Input value must be a non-negative 'int' type")

    binary_representation = bin(number)[2:]
    longest_gap = 0
    current_gap = 0

    found_one = False
    for bit in binary_representation:
        if bit == '1':
            if found_one:
                if current_gap > longest_gap:
                    longest_gap = current_gap
                current_gap = 0
            found_one = True
        elif bit == '0' and found_one:
            current_gap += 1

    return longest_gap
```

