from typing import Dict, List, Tuple
import heapq

def shortest_path_with_stops(graph: Dict[str, List[Tuple[str, int]]], start: str, end: str, max_stops: int) -> int:
    if start not in graph or end not in graph:
        return -1

    pq = [(0, start, 0)]  # (current_cost, current_node, current_stops)
    visited = set()

    while pq:
        cost, node, stops = heapq.heappop(pq)

        if node == end:
            return cost

        if (node, stops) in visited:
            continue
        visited.add((node, stops))

        if stops > max_stops:
            continue

        for neighbor, weight in graph.get(node, []):
            heapq.heappush(pq, (cost + weight, neighbor, stops + 1))

    return -1
```

