from typing import List

def max_robbery_in_circle(nums: List[int]) -> int:
    if not nums:
        return 0

    def rob_linear(houses: List[int]) -> int:
        if not houses:
            return 0
        if len(houses) == 1:
            return houses[0]

        prev1, prev2 = 0, 0
        for house in houses:
            current = max(prev1, prev2 + house)
            prev2 = prev1
            prev1 = current
        return prev1

    if len(nums) == 1:
        return nums[0]

    return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))
```

