def longest_unique_substring(input_str):
    n = len(input_str)
    if n == 0:
        return ""

    longest_substring = ""
    for i in range(n):
        substring = ""
        unique_chars = set()
        for j in range(i, n):
            if input_str[j] not in unique_chars:
                unique_chars.add(input_str[j])
                substring += input_str[j]
                if len(substring) > len(longest_substring):
                    longest_substring = substring
            else:
                break

    return longest_substring
```

