def most_frequent_integer(numbers):
    if not numbers:
        return None

    from collections import defaultdict

    frequency = defaultdict(int)

    for num in numbers:
        frequency[num] += 1

    most_frequent = None
    highest_frequency = 0

    for num, freq in sorted(frequency.items()):
        if freq > highest_frequency:
            highest_frequency = freq
            most_frequent = num

    return most_frequent
```

