def find_pairs_with_sum(nums, k):
    pairs = set()
    nums.sort()

    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == k:
            pairs.add((nums[left], nums[right]))
            left += 1
            right -= 1
        elif current_sum < k:
            left += 1
        else:
            right -= 1

    return sorted(pairs)
```

