from typing import List, Tuple

def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    if not links or n == 1:
        return 0

    def can_reach_all(max_latency: int) -> bool:
        from collections import deque

        for start in range(1, n + 1):
            visited = [False] * (n + 1)
            visited[start] = True
            queue = deque([(start, 0)])

            while queue:
                node, latency = queue.popleft()
                if latency > max_latency:
                    continue

                for u, v, w in links:
                    if (u == node and not visited[v]) or (v == node and not visited[u]):
                        visited[v] = True if u == node else True
                        queue.append((v if u == node else u, latency + w))

            if not all(visited):
                return False

        return True

    left, right = 1, 100
    result = float('inf')

    while left <= right:
        mid = (left + right) // 2
        if can_reach_all(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result
```

