        return 0

    def can_reach_all_servers(max_latency: int) -> bool:
        from collections import deque

        for start in range(1, n + 1):
            visited = [False] * (n + 1)
            queue = deque([start])
            visited[start] = True

            while queue:
                current = queue.popleft()
                for u, v, w in links:
                    if (u == current or v == current) and w <= max_latency:
                        if u == current and not visited[v]:
                            visited[v] = True
                            queue.append(v)
                        if v == current and not visited[u]:
                            visited[u] = True
                            queue.append(u)

            if not all(visited):
                return False

        return True

    left, right = 1, 100
    result = float('inf')

    while left <= right:
        mid = (left + right) // 2
        if can_reach_all_servers(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result
