            queue = deque([start])
            visited[start] = True

            while queue:
                current = queue.popleft()
                for u, v, w in links:
                    if u == current and w <= max_latency and not visited[v]:
                        visited[v] = True
                        queue.append(v)
                    if v == current and w <= max_latency and not visited[u]:
                        visited[u] = True
                        queue.append(u)

