def find_sum_combinations(numbers: List[int], target_sum: int) -> List[List[int]]:
    def backtrack(start, target, path):
        if target == 0:
            combinations.append(path)
            return
        if target < 0:
            return

        for i in range(start, len(numbers)):
            backtrack(i, target - numbers[i], path + [numbers[i]])

    combinations = []
    numbers.sort()
    backtrack(0, target_sum, [])
    return combinations
