from typing import List

def calculate_moving_median(temperatures: List[float], window_size: int) -> List[float]:
    if not temperatures:
        return []

    if window_size <= 0:
        raise ValueError("Window size must be greater than 0")

    moving_medians = []
    n = len(temperatures)

    for i in range(n):
        if i < window_size - 1:
            window = temperatures[:i + 1]
        else:
            window = temperatures[i - window_size + 1:i + 1]

        if window:
            window.sort()
            median = window[len(window) // 2]
            moving_medians.append(median)

    return moving_medians
