    digits = [char for char in s if char.isdigit()]
    result = list(s)

    digit_index = 0
    for i in range(len(result)):
        if result[i].isdigit():
            result[i] = digits[digit_index]
            digit_index += 1

    reversed_chars = [char for char in result if not char.isdigit()]
    reversed_chars.reverse()

    char_index = 0
    for i in range(len(result)):
        if not result[i].isdigit():
            result[i] = reversed_chars[char_index]
            char_index += 1

    return ''.join(result)
