    result = list(s)

    digit_index = 0
    for i in range(len(result)):
        if result[i].isdigit():
            result[i] = digits[digit_index]
            digit_index += 1

    left, right = 0, len(result) - 1
    while left < right:
        if not result[left].isdigit():
            left += 1
        elif not result[right].isdigit():
            right -= 1
        else:
            result[left], result[right] = result[right], result[left]
            left += 1
            right -= 1

    return ''.join(result)
