import operator

def evaluate_expression(expression):
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    stack = []
    num = 0
    sign = '+'

    for i, char in enumerate(expression):
        if char.isdigit():
            num = num * 10 + int(char)

        if char in ops or i == len(expression) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                stack.append(int(stack.pop() / num))

            sign = char
            num = 0

    return sum(stack)
```

