def run_length_encode(text):
    if not text:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            encoded.append(text[i - 1] + (str(count) if count > 1 else ''))
            count = 1

    encoded.append(text[-1] + (str(count) if count > 1 else ''))

    return ''.join(encoded)

def run_length_decode(encoded_text):
    if not encoded_text:
        return ""

    decoded = []
    i = 0

    while i < len(encoded_text):
        char = encoded_text[i]
        i += 1

        num = 0
        while i < len(encoded_text) and encoded_text[i].isdigit():
            num = num * 10 + int(encoded_text[i])
            i += 1

        decoded.append(char * (num if num > 0 else 1))

    return ''.join(decoded)
