from collections import defaultdict

def longest_substring_with_constraints(s: str, k: int) -> int:
    if not s or k == 0:
        return 0

    if k >= len(set(s)):
        return len(s)

    longest = 0
    n = len(s)

    for i in range(n):
        char_count = defaultdict(int)
        distinct_chars = 0

        for j in range(i, n):
            if char_count[s[j]] == 0:
                distinct_chars += 1
            char_count[s[j]] += 1

            if distinct_chars <= k:
                longest = max(longest, j - i + 1)
            else:
                break

    return longest
```

