import re

def extract_contact_info(text):
    contact_info = {}
    pattern = re.compile(r'(\w+ \w+); ([\w\.]+@[\w\.]+); (\(\d{3}\) \d{3}-\d{4}|\d{3}-\d{3}-\d{4})')

    for line in text.split('\n'):
