def min_steps_to_target(target: int) -> int:
    if target == 0:
        return 0

    step = 0
    current_sum = 0

    while current_sum != target:
        step += 1
        if (current_sum + step) == target or (current_sum - step) == target:
            current_sum += step
        elif (current_sum + step) > target:
            if (current_sum + step - 2 * step) == target:
                current_sum += step - 2 * step
            else:
                current_sum += step
        elif (current_sum - step) < target:
            if (current_sum - step + 2 * step) == target:
                current_sum -= step + 2 * step
            else:
                current_sum -= step

    return step
```

