import re

def reverse_words(s: str) -> str:
    words = re.findall(r'\b\w+\b', s)
    separators = re.findall(r'[ ,.]+', s)

    reversed_words = words[::-1]

    result = []
    word_index = 0
    separator_index = 0

    for char in s:
        if char.isalpha():
            if word_index < len(reversed_words):
                result.append(reversed_words[word_index])
                word_index += 1
        else:
            if separator_index < len(separators):
                result.append(separators[separator_index])
                separator_index += 1
            else:
                result.append(char)

    return ''.join(result)
```

