from typing import List, Tuple, Dict
from datetime import datetime, timedelta

def aggregate_sensor_data(readings: List[Tuple[str, float]]) -> Dict[str, float]:
    if not readings:
        return {}

    aggregated_data = {}

    for timestamp, value in readings:
        dt = datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
        hour_start = dt.replace(minute=0, second=0, microsecond=0)

        if hour_start not in aggregated_data:
            aggregated_data[hour_start.strftime("%Y-%m-%d %H:00:00")] = [value, 1]
        else:
            aggregated_data[hour_start.strftime("%Y-%m-%d %H:00:00")][0] += value
            aggregated_data[hour_start.strftime("%Y-%m-%d %H:00:00")][1] += 1

    result = {}
    for hour_start, (total_value, count) in aggregated_data.items():
        if count > 0:
            average_value = total_value / count
            result[hour_start] = average_value

    return result
```

