        aggregated_data[hour_start.strftime("%Y-%m-%d %H:00:00")]["sum"] += value
        aggregated_data[hour_start.strftime("%Y-%m-%d %H:00:00")]["count"] += 1

    result = {}
    for hour, data in aggregated_data.items():
        if data["count"] > 0:
            average = data["sum"] / data["count"]
            result[hour] = average

