from typing import List

def is_valid_inventory_sequence(operations: List[str]) -> bool:
    add_count = 0
    remove_count = 0
    inventory = {}

    for operation in operations:
        parts = operation.split(':')
        if len(parts) != 2:
            return False

        action, item_type = parts
        if action == 'add':
            add_count += 1
            if item_type not in inventory:
                inventory[item_type] = 0
            inventory[item_type] += 1
        elif action == 'remove':
            remove_count += 1
            if item_type not in inventory or inventory[item_type] == 0:
                return False
            inventory[item_type] -= 1
        else:
            return False

        if remove_count > add_count:
            return False

    for count in inventory.values():
        if count != 0:
            return False

    return add_count == remove_count
```

