from typing import List

def is_valid_inventory_sequence(operations: List[str]) -> bool:
    add_count = 0
    remove_count = 0
    item_stack = []

    for operation in operations:
        parts = operation.split(':')
        if len(parts) != 2:
            return False

        action, item_type = parts

        if action == 'add':
            add_count += 1
            item_stack.append(item_type)
