    odd_chars = [char for char, count in char_count.items() if count % 2 != 0]

    if len(odd_chars) > 1:
        return ""

    palindrome = []
    odd_char = ""

    for char, count in char_count.items():
        if count % 2 == 0:
            palindrome.append(char * (count // 2))
        else:
            odd_char = char
            palindrome.append(char * ((count - 1) // 2))

    if odd_char:
        palindrome.append(odd_char)
        palindrome.append(odd_char[::-1])
    else:
        palindrome.append(palindrome[0][::-1])

    return ''.join(palindrome)
