def longest_palindrome(input_string):
    from collections import Counter

    char_count = Counter(input_string)
    odd_chars = [char for char, count in char_count.items() if count % 2 != 0]

    if len(odd_chars) > 1:
        return ""

    palindrome = []
    middle_char = ""

    for char, count in char_count.items():
        if count % 2 == 0:
            palindrome.append(char * (count // 2))
        else:
            palindrome.append(char * ((count - 1) // 2))
            middle_char = char

    left_part = "".join(palindrome)
    right_part = left_part[::-1]

    if middle_char:
        return left_part + middle_char + right_part
    else:
        return left_part + right_part
