def longest_non_decreasing_subsequence(sequence: list[int]) -> int:
    if not sequence:
        return 0

    n = len(sequence)
    longest = 1
    current = 1

    for i in range(1, n):
        if sequence[i] >= sequence[i - 1]:
            current += 1
            longest = max(longest, current)
        else:
            current = 1

    return longest
