def find_sum_of_powers(n: int) -> list:
    powers_of_2 = []
    power = 1
    while power <= n:
        powers_of_2.append(power)
        power *= 2

    for i in range(len(powers_of_2)):
        for j in range(i + 1, len(powers_of_2)):
            a = powers_of_2[i]
            b = powers_of_2[j]
            if a + b == n:
                return [(a, b)]
    return []
```

