def min_operations_to_one(N):
    if N <= 1:
        return 0

    dp = [0] * (N + 1)
    dp[1] = 0

    for i in range(2, N + 1):
        dp[i] = dp[i - 1] + 1

        if i % 2 == 0:
            dp[i] = min(dp[i], dp[i // 2] + 1)

        if i % 3 == 0:
            dp[i] = min(dp[i], dp[i // 3] + 1)

    return dp[N]
```

