from typing import List

def longest_subarray_with_same_diff(arr: List[int]) -> int:
    if not arr:
        return 0

    longest_length = 1

    for i in range(len(arr)):
        diff = None
        current_length = 1

        for j in range(i + 1, len(arr)):
            if diff is None:
                diff = arr[j] - arr[j - 1]
                current_length += 1
            else:
                if arr[j] - arr[j - 1] == diff:
                    current_length += 1
                else:
                    break

        longest_length = max(longest_length, current_length)

    return longest_length
```

