    for word in lst:
        # Check if the word is a palindrome (case insensitive)
        if word.lower() == word.lower()[::-1]:
            # Reverse the word
            reversed_word = word[::-1]
            reversed_palindromes.append(reversed_word)
        else:
            reversed_palindromes.append(word)
    return reversed_palindromes
