    def evaluate(tokens):
        stack = []
        sign = '+'
        num = 0

        def apply_operator(operators, values):
            operator = operators.pop()
            right = values.pop()
            left = values.pop()
            if operator == '+':
                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                values.append(int(left / right))

        for i, token in enumerate(tokens):
            if token.isdigit():
                num = num * 10 + int(token)
            if token in "+-*/" or i == len(tokens) - 1:
                if sign == '+':
                    values.append(num)
                elif sign == '-':
                    values.append(-num)
                elif sign == '*':
                    apply_operator(operators, values)
                    operators.append(sign)
                elif sign == '/':
                    apply_operator(operators, values)
                    operators.append(sign)
                sign = token
                num = 0

        while operators:
            apply_operator(operators, values)

        return values[0]

    def tokenize(expression):
        tokens = []
        i = 0
        while i < len(expression):
            if expression[i] == ' ':
                i += 1
                continue
            if expression[i].isdigit():
                j = i
                while j < len(expression) and expression[j].isdigit():
                    j += 1
                tokens.append(expression[i:j])
                i = j
            elif expression[i] in "+-*/":
                tokens.append(expression[i])
                i += 1
            elif expression[i] == '(':
                j = i
                balance = 1
                while balance != 0:
                    j += 1
                    if expression[j] == '(':
                        balance += 1
                    elif expression[j] == ')':
                        balance -= 1
                tokens.append(expression[i:j+1])
                i = j + 1
            else:
                i += 1
        return tokens

    tokens = tokenize(expression)
    return evaluate(tokens)
