from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.files = {}
        self.directories = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files[id] = {'size': size, 'parent_id': parent_id}
        else:
            self.directories[id] = {'size': 0, 'parent_id': parent_id, 'contents': []}
            if parent_id:
                self.directories[parent_id]['contents'].append(id)

    def delete(self, id: int) -> None:
        if id in self.files:
            parent_id = self.files[id]['parent_id']
            if parent_id:
                self.directories[parent_id]['contents'].remove(id)
            del self.files[id]
        elif id in self.directories:
            parent_id = self.directories[id]['parent_id']
            if parent_id:
                self.directories[parent_id]['contents'].remove(id)
            for content_id in self.directories[id]['contents']:
                self.delete(content_id)
            del self.directories[id]

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]['size']
        elif id in self.directories:
            size = self.directories[id]['size']
            for content_id in self.directories[id]['contents']:
                size += self.get_size(content_id)
            return size
        return 0
