            self.files[id] = {'size': size, 'parent_id': parent_id}
        else:
            self.directories[id] = {'size': 0, 'parent_id': parent_id}
            if parent_id is not None:
                if parent_id in self.directories:
                    self.directories[parent_id]['size'] += size

