            if parent_id in self.directories:
                self.directories[parent_id]['size'] -= self.files[id]['size']
            del self.files[id]
        elif id in self.directories:
            self._delete_directory(id)

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]['size']
        elif id in self.directories:
            return self.directories[id]['size']
        return 0

    def _delete_directory(self, id: int) -> None:
        if id in self.directories:
            for file_id in list(self.files.keys()):
                if self.files[file_id]['parent_id'] == id:
                    self.delete(file_id)
            for dir_id in list(self.directories.keys()):
                if self.directories[dir_id]['parent_id'] == id:
                    self.delete(dir_id)
            parent_id = self.directories[id]['parent_id']
            if parent_id in self.directories:
                self.directories[parent_id]['size'] -= self.directories[id]['size']
            del self.directories[id]
