        if id in self.files_dirs:
            return

        if is_file:
            self.files_dirs[id] = {'size': size, 'parent_id': parent_id, 'is_file': True}
        else:
            self.files_dirs[id] = {'size': 0, 'parent_id': parent_id, 'is_file': False}

        if parent_id is not None:
            if parent_id in self.files_dirs and not self.files_dirs[parent_id]['is_file']:
                self.files_dirs[parent_id]['size'] += size
            else:
                return

    def delete(self, id: int) -> None:
        if id not in self.files_dirs:
            return

        if self.files_dirs[id]['is_file']:
            parent_id = self.files_dirs[id]['parent_id']
            if parent_id is not None:
                self.files_dirs[parent_id]['size'] -= self.files_dirs[id]['size']
        else:
            self._delete_directory(id)

        del self.files_dirs[id]

    def get_size(self, id: int) -> int:
        if id not in self.files_dirs:
            return 0

        if self.files_dirs[id]['is_file']:
            return self.files_dirs[id]['size']

        return self.files_dirs[id]['size']

    def _delete_directory(self, id: int) -> None:
        if id not in self.files_dirs:
            return

        if not self.files_dirs[id]['is_file']:
            for child_id in self._get_children(id):
                self.delete(child_id)

    def _get_children(self, id: int) -> list:
        children = []
        for file_dir_id, details in self.files_dirs.items():
            if details['parent_id'] == id:
                children.append(file_dir_id)
        return children
