def largest_product(nums):
    if len(nums) < 3:
        return "Not enough elements"

    nums.sort()

    n = len(nums)
    product1 = nums[n-1] * nums[n-2] * nums[n-3]
    product2 = nums[0] * nums[1] * nums[n-1]

    return max(product1, product2)
