def allocate_dorms(students):
    dorm_capacities = {"A": 100, "B": 100, "C": 80}
    dorm_allocations = {"A": [], "B": [], "C": []}

    for student in students:
        name = student["name"]
        preferences = student["preferences"]

        for pref in preferences:
            if dorm_capacities[pref] > 0:
                dorm_allocations[pref].append(name)
                dorm_capacities[pref] -= 1
                break
        else:
            for dorm in ["A", "B", "C"]:
                if dorm_capacities[dorm] > 0:
                    dorm_allocations[dorm].append(name)
                    dorm_capacities[dorm] -= 1
                    break

    return dorm_allocations
