from typing import List

def find_min_diff(num_list: List[int], n: int) -> int:
    if not num_list or len(num_list) < 2:
        return 0

    num_list.sort()
    min_diff = float('inf')

    for i in range(len(num_list) - 1):
        diff = abs(num_list[i] - num_list[i + 1])
        if diff < min_diff:
            min_diff = diff

    if n > len(num_list) * (len(num_list) - 1) // 2:
        n = len(num_list) * (len(num_list) - 1) // 2

    for i in range(len(num_list)):
        for j in range(i + 1, len(num_list)):
            diff = abs(num_list[i] - num_list[j])
