def longest_contiguous_subarray(nums):
    if not nums:
        return (0, None)

    longest_length = 1
    longest_value = nums[0]
    current_length = 1
    current_value = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == current_value:
            current_length += 1
        else:
            if current_length > longest_length:
                longest_length = current_length
                longest_value = current_value
            current_value = nums[i]
            current_length = 1

    if current_length > longest_length:
        longest_length = current_length
        longest_value = current_value

    return (longest_length, longest_value)
