def count_primes_in_range(start, end):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_count = 0
    for num in range(max(start, 2), end + 1):
        if is_prime(num):
            prime_count += 1
    return prime_count
```

