def longest_subarray_equal_even_odd(nums):
    if not nums:
        return 0

    count_map = {0: -1}
    count = 0
    max_length = 0

    for i, num in enumerate(nums):
        if num % 2 == 0:
            count += 1
        else:
            count -= 1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length
