def fibonacci_efficient(n: int) -> int:
    if n <= 1:
        return n

    def multiply(mat1, mat2):
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] += mat1[i][k] * mat2[k][j]
        return result

    def matrix_power(mat, n):
        result = [[1, 0], [0, 1]]
        while n > 0:
            if n % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            n //= 2
        return result

    fib_matrix = [[1, 1], [1, 0]]
    result_matrix = matrix_power(fib_matrix, n - 1)
    return result_matrix[0][0]
```

