from typing import List

def find_anagram_indices(text: str, pattern: str) -> List[int]:
    from collections import Counter

    if not text or not pattern:
        return []

    pattern_count = Counter(pattern)
    text_count = Counter()

    pattern_len = len(pattern)
    text_len = len(text)

    anagram_indices = []

    for i in range(text_len):
        text_count[text[i]] += 1

        if i >= pattern_len:
            if text_count[text[i - pattern_len]] == 1:
                del text_count[text[i - pattern_len]]
            else:
                text_count[text[i - pattern_len]] -= 1

        if text_count == pattern_count:
            anagram_indices.append(i - pattern_len + 1)

    return anagram_indices
```

