def validate_isbn(isbn: str) -> bool:
    isbn = isbn.replace('-', '')

    if len(isbn) == 10:
        if not isbn[:-1].isdigit() or not (isbn[-1].isdigit() or isbn[-1] == 'X'):
            return False

        total = 0
        for i, char in enumerate(isbn):
            if char == 'X':
                char = '10'
            total += (10 - i) * int(char)

        return total % 11 == 0

    elif len(isbn) == 13:
        if not isbn.isdigit():
            return False

        total = 0
        for i, char in enumerate(isbn):
            if i % 2 == 0:
                total += int(char)
            else:
                total += 3 * int(char)

        return total % 10 == 0

    return False
```

