def is_valid_rotation(matrix):
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        return False

    def rotate_90(matrix):
        return [[matrix[j][i] for j in range(n-1, -1, -1)] for i in range(n)]

    def rotate_180(matrix):
        return [row[::-1] for row in matrix[::-1]]

    def rotate_270(matrix):
        return [[matrix[j][i] for j in range(n)] for i in range(n-1, -1, -1)]

    original = matrix
    for _ in range(3):
        if matrix == original:
            return True
        matrix = rotate_90(matrix)
    if matrix == original:
        return True

    return False
```

