    if n == 0 or any(len(row) != n for row in matrix):
        return False

    def rotate_90(mat):
        return [[mat[j][i] for j in range(n-1, -1, -1)] for i in range(n)]

    def rotate_180(mat):
        return [[mat[n-1-j][n-1-i] for j in range(n)] for i in range(n)]

    def rotate_270(mat):
        return [[mat[i][n-1-j] for j in range(n-1, -1, -1)] for i in range(n)]

    original = [row[:] for row in matrix]

    for _ in range(3):
        matrix = rotate_90(matrix)
        if matrix == original:
            return True

    matrix = rotate_180(original)
    if matrix == original:
        return True

    matrix = rotate_270(original)
    if matrix == original:
        return True

    return False
