def evaluate_expression(expression):
    stack = []
    num = 0
    operator = '+'

    for i, char in enumerate(expression):
        if char.isdigit():
            num = num * 10 + int(char)

        if char in '+-*' or i == len(expression) - 1:
            if operator == '+':
                stack.append(num)
            elif operator == '-':
                stack.append(-num)
            elif operator == '*':
                stack.append(stack.pop() * num)
            elif operator == '/':
                stack.append(int(stack.pop() / num))

            operator = char
            num = 0

    result = sum(stack)
    return result
```

