def first_non_repeating_character(s: str) -> str:
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        if char != ' ':
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

    # Find the first non-repeating character
    for char in s:
        if char != ' ' and char_count[char] == 1:
            return char

    return ''
```

