def is_secure_password(password: str) -> bool:
    if len(password) < 8:
        return False

    uppercase = False
    lowercase = False
    digit = False
    special_char = False

    special_characters = "!@#$%^&*()"

    for char in password:
        if char.isupper():
            uppercase = True
        if char.islower():
            lowercase = True
        if char.isdigit():
            digit = True
        if char in special_characters:
            special_char = True

    return uppercase and lowercase and digit and special_char
