from collections import deque

def find_order_of_courses(courses, prerequisites):
    if not courses:
        return []

    # Initialize the graph and in-degree array
    graph = {i: [] for i in range(courses)}
    in_degree = [0] * courses

    # Build the graph and in-degree array
    for a, b in prerequisites:
        graph[a].append(b)
        in_degree[b] += 1

    # Find the nodes with zero in-degree
    queue = deque([i for i in range(courses) if in_degree[i] == 0])

    order = []

    while queue:
        node = queue.popleft()
        order.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) == courses:
        return order
    else:
        return []
```

