def is_valid_roman_numeral(numeral: str) -> bool:
    if not numeral:
        return False

    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    valid_chars = set(roman_map.keys())
    if not set(numeral).issubset(valid_chars):
        return False

    prev_value = 0
    count = 0

    for char in reversed(numeral):
        value = roman_map[char]

        if value > prev_value:
            if count >= 1:
                return False
            count = 1
        elif value == prev_value:
            count += 1
            if char in 'IXCM' and count > 3:
                return False
        else:
            if count >= 1:
                return False
            count = 1

        if prev_value > 0 and value >= prev_value:
            return False

        prev_value = value

    return True
```

