def max_tips(orders: list, tips: list, serve_time: list) -> int:
    if not orders or not tips or not serve_time:
        raise ValueError("Orders, tips, and serve_time lists cannot be empty")

    n = len(orders)
    if len(tips) != n or len(serve_time) != n:
        raise ValueError("The lengths of orders, tips, and serve_time lists must be the same")

    for tip in tips:
        if tip < 0:
            raise ValueError("Tip amounts must be non-negative")

    for start, end in serve_time:
        if start < 0 or end < 0 or start > 24 or end > 24 or start > end:
            raise ValueError("Invalid serve times")

    # Sort orders based on end time
    serve_time = sorted(zip(serve_time, tips, orders), key=lambda x: x[0][1])

    max_tips = 0
    dp = [0] * n

    for i in range(n):
        dp[i] = serve_time[i][1]
        for j in range(i):
            if serve_time[j][0][1] <= serve_time[i][0][0]:
                dp[i] = max(dp[i], dp[j] + serve_time[i][1])
        max_tips = max(max_tips, dp[i])

    return max_tips
