from typing import List

def next_smaller_permutation(nums: List[int]) -> List[int]:
    n = len(nums)
    if n <= 1:
        return sorted(nums, reverse=True)

    # Find the longest non-increasing suffix
    i = n - 2
    while i >= 0 and nums[i] <= nums[i + 1]:
        i -= 1

    # If the entire array is non-increasing, return the sorted array in descending order
    if i == -1:
        return sorted(nums, reverse=True)

    # Find the rightmost element that is smaller than nums[i]
    j = n - 1
    while nums[j] >= nums[i]:
        j -= 1

    # Swap nums[i] and nums[j]
    nums[i], nums[j] = nums[j], nums[i]

    # Reverse the suffix starting at i + 1
    nums[i + 1:] = reversed(nums[i + 1:])

    return nums
