class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients

    def __add__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        result = [0] * max_len
        for i in range(max_len):
            coeff1 = self.coefficients[i] if i < len(self.coefficients) else 0
            coeff2 = other.coefficients[i] if i < len(other.coefficients) else 0
            result[i] = coeff1 + coeff2
        return Polynomial(result)

    def __sub__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        result = [0] * max_len
        for i in range(max_len):
            coeff1 = self.coefficients[i] if i < len(self.coefficients) else 0
            coeff2 = other.coefficients[i] if i < len(other.coefficients) else 0
            result[i] = coeff1 - coeff2
        return Polynomial(result)

    def __mul__(self, other):
        max_len = len(self.coefficients) + len(other.coefficients) - 1
        result = [0] * max_len
        for i in range(len(self.coefficients)):
            for j in range(len(other.coefficients)):
                result[i + j] += self.coefficients[i] * other.coefficients[j]
        return Polynomial(result)

    def evaluate(self, x):
        result = 0
        for power, coeff in enumerate(reversed(self.coefficients)):
            result += coeff * (x ** power)
        return result

    def __str__(self):
        terms = []
        for power, coeff in enumerate(reversed(self.coefficients)):
            if coeff == 0:
                continue
            if power == 0:
                terms.append(f"{coeff}")
            elif power == 1:
                if coeff == 1:
                    terms.append("x")
                elif coeff == -1:
                    terms.append("-x")
                else:
                    terms.append(f"{coeff}x")
            else:
                if coeff == 1:
                    terms.append(f"x^{power}")
                elif coeff == -1:
                    terms.append(f"-x^{power}")
                else:
                    terms.append(f"{coeff}x^{power}")
        if not terms:
            return "0"
        return " + ".join(terms).replace("+ -", "- ").replace("x^1", "x").replace("x^0", "")
