def rotate_array(arr: list, k: int) -> list:
    if not arr:
        return []

    n = len(arr)
    k = k % n if k >= 0 else (n - (-k % n)) % n

    if k == 0:
        return arr

    rotated = [0] * n
    for i in range(n):
        rotated[(i + k) % n] = arr[i]

    return rotated
```

