def generate_histogram(image: list[list[int]]) -> list[int]:
    histogram = [0] * 256

    if not image or not image[0]:
        return histogram

    for row in image:
        for pixel in row:
            if 0 <= pixel <= 255:
                histogram[pixel] += 1

    return histogram
