from typing import List, Tuple

def flag_fraudulent_transactions(
    transactions: List[Tuple[str, int]],
    window: int
) -> List[str]:
    flagged_ids = []
    transaction_dict = {}

    for transaction_id, timestamp in transactions:
        if transaction_id in transaction_dict:
            prev_timestamp = transaction_dict[transaction_id]
            if timestamp - prev_timestamp <= window:
                flagged_ids.append(transaction_id)
        transaction_dict[transaction_id] = timestamp

    return flagged_ids
```

