def longest_subarray_with_sum(nums, target):
    sum_indices = {}
    current_sum = 0
    longest_subarray = []

    for i, num in enumerate(nums):
        current_sum += num

        if current_sum == target:
            longest_subarray = nums[:i+1]

        if (current_sum - target) in sum_indices:
            subarray = nums[sum_indices[current_sum - target] + 1:i+1]
            if len(subarray) > len(longest_subarray):
                longest_subarray = subarray

        if current_sum not in sum_indices:
            sum_indices[current_sum] = i

    return longest_subarray
