from typing import List, Dict, Any, Optional
import re
from collections import Counter

def advanced_string_manipulation_and_analysis(s: str, actions: List[Dict[str, Any]]) -> List[str]:
    results = []

    def substring_count(sub: str) -> str:
        count = s.count(sub)
        results.append(f"substring_count: {count}")
        return count

    def substring_replace(from_sub: str, to_sub: str, condition: Optional[str] = None) -> str:
        if condition and condition not in s:
            return s
        new_s = s.replace(from_sub, to_sub)
        results.append(f"substring_replace: {new_s}")
        return new_s

    def cipher_shift(shift: int) -> str:
        new_s = ""
        for char in s:
            if char.isalpha():
                ascii_offset = 65 if char.isupper() else 97
                new_char = chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
                new_s += new_char
            else:
                new_s += char
        results.append(f"cipher_shift: {new_s}")
        return new_s

    def find_anagrams(word: str) -> str:
        anagram_positions = []
        word_len = len(word)
        for i in range(len(s) - word_len + 1):
            substring = s[i:i + word_len]
            if sorted(substring) == sorted(word):
                anagram_positions.append(i)
        results.append(f"find_anagrams: {anagram_positions}")
        return anagram_positions

    def word_frequency() -> str:
        words = s.split()
        frequency = Counter(words)
        results.append(f"word_frequency: {frequency}")
        return frequency

    def pattern_match(pattern: str) -> str:
        matches = [match.start() for match in re.finditer(pattern, s)]
        results.append(f"pattern_match: {matches}")
        return matches

    for action in actions:
        action_type = action.get("type")
        if action_type == "substring_count":
            value = action.get("value")
            if value is None:
                continue
            substring_count(value)
        elif action_type == "substring_replace":
            from_sub = action.get("from")
            to_sub = action.get("to")
            condition = action.get("if_contains")
            if from_sub is None or to_sub is None:
                continue
            substring_replace(from_sub, to_sub, condition)
        elif action_type == "cipher_shift":
            shift = action.get("shift")
